export function resolveMeshyImageTo3dConfig(
  env: { get(key: string): string | undefined } = Deno.env,
  apiKeyOverride?: string | null,
): MeshyImageTo3dProviderConfig | null {
  const apiKey = apiKeyOverride !== undefined
    ? (apiKeyOverride?.trim() ?? '')
    : (env.get('MESHY_API_KEY')?.trim() ?? '');
  if (!apiKey) return null;

  const baseUrl = (env.get('MESHY_API_BASE_URL')?.trim() || DEFAULT_BASE).replace(/\/+$/, '');
  const model = env.get('MESHY_IMAGE_TO_3D_MODEL')?.trim() || DEFAULT_MODEL;

  return { apiKey, baseUrl, model };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function parseCreateResponse(body: unknown): string {
  if (!isRecord(body) || typeof body.result !== 'string' || !body.result.trim()) {
    throw new Error('Meshy create response missing result id');
  }
  return body.result.trim();
}

function parseTask(body: unknown): MeshyImageTo3dTask {
  if (!isRecord(body) || typeof body.id !== 'string' || typeof body.status !== 'string') {
    throw new Error('Meshy task response invalid');
  }
  const status = body.status as MeshyTaskStatus;
  const progress = typeof body.progress === 'number' && Number.isFinite(body.progress)
    ? Math.max(0, Math.min(100, Math.round(body.progress)))
    : 0;

  let model_urls: { glb?: string } | undefined;
  if (isRecord(body.model_urls)) {
    const glb = typeof body.model_urls.glb === 'string' && body.model_urls.glb.startsWith('https://')
      ? body.model_urls.glb
      : undefined;
    if (glb) model_urls = { glb };
  } else if (typeof body.model_url === 'string' && body.model_url.startsWith('https://')) {
    model_urls = { glb: body.model_url };
  }

  const task_error = isRecord(body.task_error)
    ? { message: typeof body.task_error.message === 'string' ? body.task_error.message : undefined }
    : undefined;

  return { id: body.id, status, progress, model_urls, task_error };
}

export function createLiveMeshyImageTo3dProvider(
  config: MeshyImageTo3dProviderConfig,
  fetchImpl: FetchLike = fetch,
): MeshyImageTo3dProvider {
  return {
    async createTask(input: MeshyImageTo3dCreateInput): Promise<{ taskId: string }> {
      // Defaults keep item-model3d path stable; avatar passes full adapter-mapped options.
      const textureResolution =
        input.textureResolution === '4k' || input.textureResolution === '8k' || input.textureResolution === '2k'
          ? input.textureResolution
          : '2k';
      const payload: Record<string, unknown> = {
        ai_model: (input.aiModel?.trim() || config.model),
        should_texture: true,
        texture_resolution: textureResolution,
        target_formats: ['glb'],
        enable_pbr: input.enablePbr !== false,
      };
      if (input.modelType === 'standard' || input.modelType === 'smart-topology') {
        payload.model_type = input.modelType;
      }
      if (input.imageEnhancement === true) {
        payload.image_enhancement = true;
      }
      if (input.ultraMode === true) {
        payload.ultra_mode = true;
      }
      if (input.topology === 'triangle' || input.topology === 'quad') {
        payload.topology = input.topology;
      }
      if (input.savePreRemeshedModel === true) {
        payload.save_pre_remeshed_model = true;
      }
      if (input.kind === 'input_task_id') {
        payload.input_task_id = input.inputTaskId;
      } else {
        payload.image_url = input.imageUrl;
      }
      const texturePrompt = input.texturePrompt?.trim();
      if (texturePrompt) {
        payload.texture_prompt = texturePrompt.slice(0, 800);
      }
      if (input.poseMode === 'a-pose' || input.poseMode === 't-pose') {
        payload.pose_mode = input.poseMode;
      } else if (input.poseMode === '') {
        payload.pose_mode = '';
      }
      if (input.shouldRemesh === true) {
        payload.should_remesh = true;
        const poly = typeof input.targetPolycount === 'number' && Number.isFinite(input.targetPolycount)
          ? Math.max(100, Math.min(300_000, Math.round(input.targetPolycount)))
          : 50_000;
        payload.target_polycount = poly;
      } else if (input.shouldRemesh === false) {
        payload.should_remesh = false;
      }
      if (
        input.modelType === 'smart-topology'
        && typeof input.targetPolycount === 'number'
        && Number.isFinite(input.targetPolycount)
      ) {
        payload.target_polycount = Math.max(100, Math.min(15_000, Math.round(input.targetPolycount)));
      }

      const response = await fetchImpl(`${config.baseUrl}/image-to-3d`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${config.apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(30_000),
      });

      if (response.status === 402) throw new Error('MESHY_CREDITS');
      if (response.status === 429) throw new Error('MESHY_RATE');
      if (!response.ok) throw new Error(`Meshy image-to-3d create failed (${response.status})`);

      const body: unknown = await response.json();
      return { taskId: parseCreateResponse(body) };
    },

    async getTask(taskId: string): Promise<MeshyImageTo3dTask> {
      const response = await fetchImpl(
        `${config.baseUrl}/image-to-3d/${encodeURIComponent(taskId)}`,
        {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${config.apiKey}`,
            Accept: 'application/json',
          },
          signal: AbortSignal.timeout(20_000),
        },
      );
      if (!response.ok) throw new Error(`Meshy image-to-3d status failed (${response.status})`);
      const body: unknown = await response.json();
      return parseTask(body);
    },
  };
}

export function createMockMeshyImageTo3dProvider(options?: {
  failCreate?: boolean;
  failStatus?: boolean;
  modelUrl?: string;
}): MeshyImageTo3dProvider {
  const taskId = 'mock-meshy-i23d-001';
  let polls = 0;
  return {
    async createTask(_input: MeshyImageTo3dCreateInput): Promise<{ taskId: string }> {
      if (options?.failCreate) throw new Error('MESHY_CREDITS');
      return { taskId };
    },
    async getTask(id: string): Promise<MeshyImageTo3dTask> {
      if (options?.failStatus) throw new Error('Meshy status failed (500)');
      polls += 1;
      if (polls < 2) {
        return { id, status: 'IN_PROGRESS', progress: 40 };
      }
      return {
        id,
        status: 'SUCCEEDED',
        progress: 100,
        model_urls: {
          glb: options?.modelUrl ?? 'https://assets.meshy.ai/mock/output.glb',
        },
      };
    },
  };
}

export function mapMeshyImageTo3dStatusToJob(status: MeshyTaskStatus): {
  status: 'waiting' | 'generating' | 'succeeded' | 'failed' | 'canceled';
  progress: number;
} {
  switch (status) {
    case 'PENDING':
      return { status: 'waiting', progress: 5 };
    case 'IN_PROGRESS':
      return { status: 'generating', progress: 50 };
    case 'SUCCEEDED':
      return { status: 'succeeded', progress: 100 };
    case 'CANCELED':
      return { status: 'canceled', progress: 0 };
    case 'FAILED':
    default:
      return { status: 'failed', progress: 0 };
  }
}

CORS_OPTS: CorsOptions = {
  methods: 'POST, OPTIONS',
  envKeys: ['CHARACTER_AI_ALLOWED_ORIGIN'],
  allowLocalhostWhenConfigured: true,
  missingOriginPolicy: 'configured-or-star',
}

function publicMeshyFailure(kind: PublicMeshyFailure): string {
  switch (kind) {
    case 'generate':
      return 'Meshy-Generierung fehlgeschlagen.';
    case 'remesh':
      return 'Modell-Verkleinerung fehlgeschlagen.';
    case 'rig':
      return 'Auto-Rig fehlgeschlagen.';
    case 'download':
      return 'Modell-Download fehlgeschlagen.';
    case 'store':
      return 'Speichern des Modells fehlgeschlagen.';
    case 'status':
      return 'Meshy-Status konnte nicht geladen werden.';
    case 'unavailable':
      return 'Meshy nicht erreichbar.';
    case 'no_model':
      return 'Meshy lieferte keine Modell-URL.';
  }
}

async function resolveOwnedCharacterId(
  characterId: string | null,
  userId: string,
  supabaseUrl: string,
  serviceHeaders: Record<string, string>,
): Promise<string | null> {
  if (!characterId || !UUID_RE.test(characterId)) return null;
  const res = await fetch(
    `${supabaseUrl}/rest/v1/characters?id=eq.${encodeURIComponent(characterId)}&owner_user_id=eq.${encodeURIComponent(userId)}&select=id&limit=1`,
    { headers: serviceHeaders },
  );
  if (!res.ok) return null;
  const rows: unknown = await res.json();
  if (!Array.isArray(rows) || rows.length === 0) return null;
  return characterId;
}

type AvatarMeshyTask = {
  status: string;
  progress: number;
  model_urls?: { glb?: string };
  task_error?: { message?: string };
};

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === 'object' && value !== null;
}

function assertOwnerScopedStoragePath(userId: string, storagePath: string): string {
  const normalized = storagePath.trim().replace(/^\/+/, '');
  const prefix = `${userId}/`;
  if (
    !normalized
    || normalized.includes('..')
    || normalized.includes('\\')
    || !normalized.startsWith(prefix)
  ) {
    throw new Error('Ungültiger Storage-Pfad für diesen Account.');
  }
  return normalized;
}

function getCorsHeaders(request: Request): HeadersInit {
  return corsHeaders(request, CORS_OPTS);
}

function json(status: number, body: JsonRecord, request: Request): Response {
  return sharedJsonResponse(request, body, status, CORS_OPTS);
}

function validatePrompt(prompt: unknown): { ok: true; prompt: string } | { ok: false; message: string } {
  if (typeof prompt !== 'string') return { ok: false, message: 'Prompt fehlt.' };
  const normalized = prompt.trim().replace(/\s+/g, ' ');
  if (normalized.length < 8) return { ok: false, message: 'Prompt zu kurz (min. 8 Zeichen).' };
  if (normalized.length > 500) return { ok: false, message: 'Prompt zu lang (max. 500 Zeichen).' };
  return { ok: true, prompt: normalized };
}

function validateOptionalTexturePrompt(
  prompt: unknown,
): { ok: true; prompt: string } | { ok: false; message: string } {
  if (prompt === undefined || prompt === null || prompt === '') {
    return { ok: true, prompt: '' };
  }
  if (typeof prompt !== 'string') return { ok: false, message: 'Textur-Prompt ungültig.' };
  const normalized = prompt.trim().replace(/\s+/g, ' ');
  if (normalized.length > 500) return { ok: false, message: 'Textur-Prompt zu lang (max. 500 Zeichen).' };
  return { ok: true, prompt: normalized };
}

function validateImageDataUri(
  value: unknown,
): { ok: true; dataUri: string } | { ok: false; message: string } {
  if (typeof value !== 'string') return { ok: false, message: 'Bild fehlt.' };
  const normalized = value.trim();
  const match = /^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/=\s]+)$/i.exec(normalized);
  if (!match) return { ok: false, message: 'Bild muss PNG, JPEG oder WebP als Data-URI sein.' };
  const b64 = match[2]!.replace(/\s+/g, '');
  const approxBytes = Math.floor((b64.length * 3) / 4);
  if (approxBytes <= 0) return { ok: false, message: 'Bild ist leer.' };
  if (approxBytes > IMAGE_MAX_BYTES) {
    return { ok: false, message: 'Bild zu groß (max. 4 MB).' };
  }
  return { ok: true, dataUri: `data:image/${match[1]!.toLowerCase()};base64,${b64}` };
}

function jobRuntimePolycount(job: JsonRecord): number {
  const settings = isRecord(job.generation_settings) && isRecord(job.generation_settings.settings)
    ? job.generation_settings.settings
    : null;
  const runtime = settings && typeof settings.runtimePolycount === 'number'
    ? settings.runtimePolycount
    : null;
  if (typeof runtime === 'number' && Number.isFinite(runtime)) {
    return Math.max(10_000, Math.min(100_000, Math.round(runtime)));
  }
  return AVATAR_MESHY_REMESH_TARGET_POLYCOUNT;
}

function jobKeepMaster(job: JsonRecord): boolean {
  const settings = isRecord(job.generation_settings) && isRecord(job.generation_settings.settings)
    ? job.generation_settings.settings
    : null;
  return settings?.keepMaster === true;
}

function jobPipelineFlags(job: JsonRecord): JsonRecord {
  const gs = isRecord(job.generation_settings) ? job.generation_settings : null;
  return gs && isRecord(gs.pipeline) ? gs.pipeline : {};
}

function withPipelineFlag(job: JsonRecord, key: string, value: boolean): JsonRecord {
  const base = isRecord(job.generation_settings) ? { ...job.generation_settings } : {};
  const pipeline = isRecord(base.pipeline) ? { ...base.pipeline } : {};
  pipeline[key] = value;
  return { ...base, pipeline };
}

function isPipelineClaimId(id: string): boolean {
  return id.startsWith(PIPELINE_CLAIM_PREFIX);
}

function parseGenerationMode(value: unknown): GenerationMode {
  return value === 'image' ? 'image' : 'text';
}

function jobGenerationMode(job: JsonRecord): GenerationMode {
  return job.generation_mode === 'image' ? 'image' : 'text';
}

async function getUserId(request: Request, supabaseUrl: string, anonKey: string): Promise<string | null> {
  const auth = request.headers.get('Authorization');
  if (!auth) return null;
  const response = await fetch(`${supabaseUrl}/auth/v1/user`, {
    headers: { Authorization: auth, apikey: anonKey },
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) return null;
  const body: unknown = await response.json();
  if (!isRecord(body) || typeof body.id !== 'string') return null;
  return body.id;
}

function resolveTextProvider(apiKey: string | null): MeshyTextTo3dProvider | null {
  if (Deno.env.get('MESHY_AVATAR_USE_MOCK') === '1') {
    return createMockMeshyTextTo3dProvider();
  }
  const config = resolveMeshyTextTo3dConfig(Deno.env, apiKey);
  if (!config) return null;
  return createLiveMeshyTextTo3dProvider(config);
}

function resolveImageProvider(apiKey: string | null): MeshyImageTo3dProvider | null {
  if (Deno.env.get('MESHY_AVATAR_USE_MOCK') === '1') {
    return createMockMeshyImageTo3dProvider();
  }
  const config = resolveMeshyImageTo3dConfig(Deno.env, apiKey);
  if (!config) return null;
  return createLiveMeshyImageTo3dProvider(config);
}

function resolveRemeshProvider(apiKey: string | null): MeshyRemeshProvider | null {
  if (Deno.env.get('MESHY_AVATAR_USE_MOCK') === '1') {
    return createMockMeshyRemeshProvider();
  }
  if (!apiKey?.trim()) return null;
  const baseUrl = Deno.env.get('MESHY_API_BASE_URL')?.trim()
    || 'https://api.meshy.ai/openapi/v1';
  return createLiveMeshyRemeshProvider({ apiKey: apiKey.trim(), baseUrl });
}

function resolveRiggingProvider(apiKey: string | null): MeshyRiggingProvider | null {
  if (Deno.env.get('MESHY_AVATAR_USE_MOCK') === '1') {
    return createMockMeshyRiggingProvider();
  }
  if (!apiKey?.trim()) return null;
  const baseUrl = Deno.env.get('MESHY_API_BASE_URL')?.trim()
    || 'https://api.meshy.ai/openapi/v1';
  return createLiveMeshyRiggingProvider({ apiKey: apiKey.trim(), baseUrl });
}

function toAvatarTask(task: MeshyTextTo3dTask | MeshyImageTo3dTask): AvatarMeshyTask {
  return {
    status: task.status,
    progress: task.progress,
    model_urls: task.model_urls,
    task_error: task.task_error,
  };
}

async function fetchAvatarMeshyTask(
  mode: GenerationMode,
  apiKey: string | null,
  taskId: string,
): Promise<AvatarMeshyTask | null> {
  if (mode === 'image') {
    const provider = resolveImageProvider(apiKey);
    if (!provider) return null;
    return toAvatarTask(await provider.getTask(taskId));
  }
  const provider = resolveTextProvider(apiKey);
  if (!provider) return null;
  return toAvatarTask(await provider.getTask(taskId));
}
